IDS = {
0x00:'kEnd',0x01:'kHeader',0x02:'kArchiveProperties',0x03:'kAdditionalStreamsInfo',
0x04:'kMainStreamsInfo',0x05:'kFilesInfo',0x06:'kPackInfo',0x07:'kUnPackInfo',
0x08:'kSubStreamsInfo',0x09:'kSize',0x0A:'kCRC',0x0B:'kFolder',0x0C:'kCodersUnPackSize',
0x0D:'kNumUnPackStream',0x0E:'kEmptyStream',0x0F:'kEmptyFile',0x10:'kAnti',
0x11:'kName',0x12:'kCTime',0x13:'kATime',0x14:'kMTime',0x15:'kWinAttrib',
0x16:'kComment',0x17:'kEncodedHeader',0x18:'kStartPos',0x19:'kDummy',
0x1A:'kNtSecure',0x1B:'kParent',0x1C:'kIsAux',0x1D:'kPosixAttrib',
0x1E:'kSubType',0x1F:'kUnknown1f',0x20:'kUnknown20',0x21:'kUnknown21',
0x22:'kTimeZone',0x23:'kArcFileName',
}

class R:
    def __init__(self,b,base=0):
        self.b=b; self.i=0; self.base=base
    def byte(self):
        v=self.b[self.i]; self.i+=1; return v
    def num(self):
        start=self.i
        first=self.byte(); mask=0x80; value=0
        for i in range(8):
            if not (first & mask):
                value |= (first & (mask-1)) << (8*i)
                return value,self.b[start:self.i]
            value |= self.b[self.i] << (8*i); self.i+=1
            mask >>= 1
        return value,self.b[start:self.i]
    def n(self):
        return self.num()[0]
    def bits(self,cnt):
        res=[]; b=0; mask=0
        for i in range(cnt):
            if mask==0:
                b=self.byte(); mask=0x80
            res.append(1 if (b&mask) else 0); mask>>=1
        return res
    def boolvec(self,cnt):
        allDef=self.byte()
        if allDef: return [1]*cnt, allDef
        return self.bits(cnt), allDef

def dump(hdr, base, out=sys.stdout):
    r=R(hdr); depth=0
    def p(*a):
        out.write('  '*depth + ' '.join(str(x) for x in a) + '\n')
    # generic sequential dump with structure awareness
    def rd_streamsinfo():
        nonlocal depth
        numPack=0; folders=[]; packsizes=[]
        while True:
            off=r.i; t=r.byte()
            p('@%04d %02x %s'%(off,t,IDS.get(t,'?')))
            if t==0x00: break
            depth+=1
            if t==0x06: # PackInfo
                packpos=r.n(); numPack=r.n()
                p('PackPos=%d NumPackStreams=%d'%(packpos,numPack))
                while True:
                    off2=r.i; t2=r.byte()
                    p('@%04d %02x %s'%(off2,t2,IDS.get(t2,'?')))
                    if t2==0: break
                    if t2==0x09:
                        packsizes=[r.n() for _ in range(numPack)]
                        p('  PackSizes=',packsizes)
                    elif t2==0x0A:
                        d,a=r.boolvec(numPack); p('  defined',d)
                        crcs=[struct.unpack('<I',r.b[r.i+4*k:r.i+4*k+4])[0] for k in range(sum(d))]
                        r.i+=4*sum(d); p('  CRCs',[hex(c) for c in crcs])
                    else: raise Exception('unk in packinfo %02x'%t2)
            elif t==0x07: # UnPackInfo
                while True:
                    off2=r.i; t2=r.byte()
                    p('@%04d %02x %s'%(off2,t2,IDS.get(t2,'?')))
                    if t2==0: break
                    if t2==0x0B:
                        numFolders=r.n(); ext=r.byte()
                        p('  NumFolders=%d External=%d'%(numFolders,ext))
                        for fi in range(numFolders):
                            nc=r.n(); coders=[]; tin=0; tout=0
                            for ci in range(nc):
                                fl=r.byte(); idsize=fl&0x0F
                                cid=r.b[r.i:r.i+idsize]; r.i+=idsize
                                nin=nout=1
                                if fl&0x10: nin=r.n(); nout=r.n()
                                props=b''
                                if fl&0x20:
                                    ps=r.n(); props=r.b[r.i:r.i+ps]; r.i+=ps
                                tin+=nin; tout+=nout
                                coders.append((fl,cid.hex(),nin,nout,props.hex()))
                                p('  folder%d coder%d flags=0x%02x id=%s nin=%d nout=%d props=%s'%(fi,ci,fl,cid.hex(),nin,nout,props.hex()))
                            nbp=tout-1
                            bps=[]
                            for _ in range(nbp):
                                bps.append((r.n(),r.n()))
                            if nbp: p('  folder%d bindpairs=%s'%(fi,bps))
                            npk=tin-nbp
                            if npk!=1:
                                idx=[r.n() for _ in range(npk)]
                                p('  folder%d packedIdx=%s'%(fi,idx))
                            folders.append((coders,tout,npk))
                    elif t2==0x0C:
                        for fi,(coders,tout,npk) in enumerate(folders):
                            sz=[r.n() for _ in range(tout)]
                            p('  folder%d unpackSizes=%s'%(fi,sz))
                    elif t2==0x0A:
                        d,a=r.boolvec(len(folders)); p('  folderCRC defined',d,'allDefByte=%d'%a)
                        for k in range(sum(d)):
                            p('  crc=0x%08x'%struct.unpack('<I',r.b[r.i:r.i+4])[0]); r.i+=4
                    else: raise Exception('unk in unpackinfo %02x'%t2)
            elif t==0x08: # SubStreamsInfo
                nums=[1]*len(folders)
                while True:
                    off2=r.i; t2=r.byte()
                    p('@%04d %02x %s'%(off2,t2,IDS.get(t2,'?')))
                    if t2==0: break
                    if t2==0x0D:
                        nums=[r.n() for _ in folders]; p('  NumUnpackStreams=',nums)
                    elif t2==0x09:
                        sizes=[]
                        for fi in range(len(folders)):
                            if nums[fi]==0: continue
                            for k in range(nums[fi]-1): sizes.append(r.n())
                        p('  sizes(all but last per folder)=',sizes)
                    elif t2==0x0A:
                        tot=sum(nums)
                        d,a=r.boolvec(tot); p('  defined',d,'allDefByte=%d'%a)
                        for k in range(sum(d)):
                            p('  crc=0x%08x'%struct.unpack('<I',r.b[r.i:r.i+4])[0]); r.i+=4
                    else: raise Exception('unk in substreams %02x'%t2)
            depth-=1
    def rd_filesinfo():
        nonlocal depth
        numFiles=r.n(); p('NumFiles=%d'%numFiles)
        numEmptyStream=0
        while True:
            off=r.i; t=r.byte()
            if t==0:
                p('@%04d 00 kEnd(FilesInfo)'%off); break
            size,szb=r.num()
            p('@%04d %02x %s size=%d(sizebytes=%s) dataStart=@%04d'%(off,t,IDS.get(t,'?'),size,szb.hex(),r.i))
            end=r.i+size
            depth+=1
            if t==0x0E:
                bv=r.bits(numFiles); numEmptyStream=sum(bv)
                p('emptyStream bits=%s raw=%s'%(''.join(map(str,bv)), r.b[r.i-((numFiles+7)//8):r.i].hex()))
            elif t in (0x0F,0x10):
                bv=r.bits(numEmptyStream)
                p('bits=%s'%''.join(map(str,bv)))
            elif t==0x11:
                ext=r.byte(); data=r.b[r.i:end]
                p('external=%d'%ext)
                names=data.decode('utf-16-le').split('\x00')
                p('names=%r'%names)
            elif t in (0x12,0x13,0x14):
                d,a=r.boolvec(numFiles); p('defined=%s allDefByte=%d'%(d,a))
                ext=r.byte(); p('external=%d'%ext)
                for k in range(sum(d)):
                    v=struct.unpack('<Q',r.b[r.i:r.i+8])[0]; r.i+=8
                    p('FILETIME=0x%016x raw=%s -> %s'%(v,r.b[r.i-8:r.i].hex(),ft(v)))
            elif t==0x15:
                d,a=r.boolvec(numFiles); p('defined=%s allDefByte=%d'%(d,a))
                ext=r.byte(); p('external=%d'%ext)
                for k in range(sum(d)):
                    v=struct.unpack('<I',r.b[r.i:r.i+4])[0]; r.i+=4
                    p('attrib=0x%08x low16=0x%04x hi16=0x%04x(oct %o)'%(v,v&0xffff,v>>16,v>>16))
            elif t==0x19:
                p('dummy raw=%s'%r.b[r.i:end].hex())
            else:
                p('RAW=%s'%r.b[r.i:end].hex())
            depth-=1
            r.i=end
    off=r.i; t=r.byte()
    p('@%04d %02x %s'%(off,t,IDS.get(t,'?')))
    if t==0x17:
        p('--- encoded header StreamsInfo ---'); depth+=1; rd_streamsinfo(); depth-=1; return
    assert t==0x01
    depth+=1
    while True:
        off=r.i; t=r.byte()
        p('@%04d %02x %s'%(off,t,IDS.get(t,'?')))
        if t==0: break
        depth+=1
        if t==0x04: rd_streamsinfo()
        elif t==0x05: rd_filesinfo()
        elif t==0x02:
            while True:
                pid=r.n()
                if pid==0: break
                sz=r.n(); p('prop %d raw=%s'%(pid,r.b[r.i:r.i+sz].hex())); r.i+=sz
        else:
            p('UNHANDLED'); break
        depth-=1
    p('consumed %d of %d'%(r.i,len(hdr)))

import datetime
def ft(v):
    try:
        return (datetime.datetime(1601,1,1)+datetime.timedelta(microseconds=v/10)).isoformat()+' (rem100ns=%d)'%(v%10)
    except Exception as e: return 'ERR'

def main(path):
    d=open(path,'rb').read()
    print('FILE %s size=%d'%(path,len(d)))
    print('sig      =',d[0:6].hex())
    print('version  = %d.%d'%(d[6],d[7]))
    shcrc=struct.unpack('<I',d[8:12])[0]
    calc=zlib.crc32(d[12:32])&0xffffffff
    print('StartHdrCRC=0x%08x calc=0x%08x %s'%(shcrc,calc,'OK' if shcrc==calc else 'BAD'))
    nho,nhs=struct.unpack('<QQ',d[12:28])
    nhc=struct.unpack('<I',d[28:32])[0]
    print('NextHeaderOffset=%d (0x%x) -> abs %d'%(nho,nho,32+nho))
    print('NextHeaderSize  =%d (0x%x)'%(nhs,nhs))
    hdr=d[32+nho:32+nho+nhs]
    print('NextHeaderCRC=0x%08x calc=0x%08x %s'%(nhc,zlib.crc32(hdr)&0xffffffff,'OK' if nhc==(zlib.crc32(hdr)&0xffffffff) else 'BAD'))
    print('packed area = bytes 32 .. %d (%d bytes)'%(32+nho,nho))
    print('--- header hex (offsets relative to header start) ---')
    for i in range(0,len(hdr),16):
        print('%04d  %-47s  %s'%(i,' '.join('%02x'%c for c in hdr[i:i+16]),
            ''.join(chr(c) if 32<=c<127 else '.' for c in hdr[i:i+16])))
    print('--- parse ---')
    dump(hdr,32+nho)

if __name__=='__main__':
    for p in sys.argv[1:]: main(p); print()
